/**
 * The bank's data, read from the same JSON the brain reads (../../data):
 * `products.json` (authored catalogue, rates, fees) and `customer.json` (the one
 * signed-in customer, generated by data/build_customer.py). Dates are kept as
 * `days_ago` / `days_from_now` and turned into dates against today here, exactly
 * as the brain does, so "last month" means the same month on both sides.
 */
import productsJson from "../../../data/products.json";
import customerJson from "../../../data/customer.json";

export type AccountId = "sb" | "ca";
export type TxnAccount = AccountId | "cc";
export type Direction = "debit" | "credit";

