// ─── Dates ────────────────────────────────────────────────────────────────

/** Today at local midnight. */
export function today(): Date {
  const d = new Date();
  d.setHours(0, 0, 0, 0);
  return d;
}

export function daysAgo(n: number): Date {
  const d = today();
  d.setDate(d.getDate() - n);
  return d;
}

export function daysFromNow(n: number): Date {
  return daysAgo(-n);
}

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const MONTHS_LONG = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

/** 07 Nov 2026 */
export function fmtDate(d: Date): string {
  return `${String(d.getDate()).padStart(2, "0")} ${MONTHS[d.getMonth()]} ${d.getFullYear()}`;
}

/** "YYYY-MM" of a date. */
export function monthKey(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
}

/** "October 2026" */
export function monthName(key: string): string {
  const [y, m] = key.split("-").map(Number);
  return `${MONTHS_LONG[m - 1]} ${y}`;
}

/** days_ago bounds [from, to] of a month key, clipped to today. */
export function monthBounds(key: string): { from_days_ago: number; to_days_ago: number } {
  const [y, m] = key.split("-").map(Number);
  const first = new Date(y, m - 1, 1);
  const last = new Date(y, m, 0);
  const t = today().getTime();
  const day = 86400000;
  return {
    from_days_ago: Math.round((t - first.getTime()) / day),
    to_days_ago: Math.max(0, Math.round((t - last.getTime()) / day)),
  };
}

// ─── Money ────────────────────────────────────────────────────────────────

/** Indian grouping: 1,25,000. */
export function inr(n: number, opts: { paise?: boolean } = {}): string {
  const paise = opts.paise ?? !Number.isInteger(Math.round(n * 100) / 100);
  const s = Math.abs(n).toLocaleString("en-IN", { minimumFractionDigits: paise ? 2 : 0, maximumFractionDigits: paise ? 2 : 0 });
  return `${n < 0 ? "−" : ""}₹${s}`;
}

// ─── Lookups ──────────────────────────────────────────────────────────────

export const accountById = (id: string) => customer.accounts.find((a) => a.id === id);
export const cardById = (id: string) => customer.cards.find((c) => c.id === id);
export const txnById = (id: string) => customer.transactions.find((t) => t.id === id);
export const creditCardProduct = (id: string) => products.credit_cards.find((c) => c.id === id);
export const loanProduct = (id: string) => products.loans.find((l) => l.id === id);
export const billerById = (id: string) => products.billers.find((b) => b.id === id);
export const categoryName = (id: string) => products.spend_categories.find((c) => c.id === id)?.name ?? id;

/** The transaction filter both the page and the brain apply (CONTRACT.md, txn.find). */
export interface TxnFilter {
  account?: "all" | TxnAccount | null;
  category?: string | null;
  query?: string | null;
  from_days_ago?: number | null;
  to_days_ago?: number | null;
  min_amount?: number | null;
  max_amount?: number | null;
  direction?: "any" | Direction | null;
  label?: string | null;
}

export function filterTxns(all: Txn[], f: TxnFilter): Txn[] {
  const q = (f.query ?? "").trim().toLowerCase();
  return all
    .filter((t) => !f.account || f.account === "all" || t.account === f.account)
    .filter((t) => !f.category || t.category === f.category)
    .filter((t) => !q || `${t.merchant} ${t.description}`.toLowerCase().includes(q))
    .filter((t) => f.from_days_ago == null || t.days_ago <= f.from_days_ago)
    .filter((t) => f.to_days_ago == null || t.days_ago >= f.to_days_ago)
    .filter((t) => f.min_amount == null || t.amount >= f.min_amount)
    .filter((t) => f.max_amount == null || t.amount <= f.max_amount)
    .filter((t) => !f.direction || f.direction === "any" || t.direction === f.direction)
    .sort((a, b) => a.days_ago - b.days_ago || b.id.localeCompare(a.id));
}
